def method_props(method):
    table = {'GET': (True, True), 'HEAD': (True, True), 'OPTIONS': (True, True), 'TRACE': (True, True),
             'PUT': (False, True), 'DELETE': (False, True), 'POST': (False, False), 'PATCH': (False, False)}
    m = method.upper()
    if m not in table:
        raise ValueError(method)
    return table[m]

